    } else {
        if (str[S - 1] != '_') {
            if (value(str, S - 1) != end2) return 0;
        }
    }
    int total = 1;
    for (int i = 0; i < S - 2; i++) {
        if (i == 0) {
            if (str[i] == 'X' && X_val == 0) return 0;
            if (value(str, i) == 0) return 0;
        }
        if (str[i] == '_') {
