            else {
                X_val = 10;
                if (i == 0) total *= 9;
                else total *= 10;
            }
        }
    }
    return total;
}

int value(const std::string& str, int pos) {
    if (str[pos] == '_' || str[pos] == 'X') return -1;
    return str[pos] - '0';
